def de(eid, work, author, year, slots, scheme, note, quote='', url='', ver='snippet'):
    r = row(entry_id=eid, work=work, author_editor=author, year_read=year, language='de', access=FTS, url=url, verification_level=ver, title_page_checked='no', census_frame='strand_b_de_1780_1860', enumerates='partial', scheme_family=scheme, quote=quote, notes=note, organized_by='school history or table')
    r.update(slots)
    hi = [int(v) for k, v in slots.items() if v.isdigit()]
    r['highest_ordinal'] = str(max(hi)) if hi else ''
    return r

