def append(path, rows, cols=None):
    p = os.path.join(ROOT, path)
    exists = os.path.exists(p)
    have = set()
    if exists:
        with open(p, newline='', encoding='utf-8') as f:
            rd = csv.DictReader(f); cols = rd.fieldnames; have = {r['entry_id'] for r in rd}
    cols = cols or COLS
    new = [r for r in rows if r['entry_id'] not in have]
    with open(p, 'a' if exists else 'w', newline='', encoding='utf-8') as f:
        w = csv.DictWriter(f, fieldnames=cols, extrasaction='ignore')
        if not exists: w.writeheader()
        for r in new: w.writerow({c: r.get(c, '') for c in cols})
    print(path, '+', len(new))

